import { FaIcon } from '@atomic/atm.fa-icon';
import type { FieldStateType } from '@atomic/obj.form/form.model';
import * as React from 'react';
import { style } from './select.component.style';

export interface SelectOption {
  value: string;
  label: string;
}

export interface SelectProps extends FieldStateType, React.SelectHTMLAttributes<HTMLSelectElement> {
  options: SelectOption[];
}

export const Select = React.forwardRef(
  ({ invalid, className, options, ...props }: SelectProps, ref: React.ForwardedRef<HTMLSelectElement>) => {
    return (
      <div className={style().wrapper()}>
        <select ref={ref} className={style().field({ invalid, className })} {...props}>
          {options.map(option => (
            <option key={option.value} value={option.value}>
              {option.label}
            </option>
          ))}
        </select>
        <FaIcon.ArrowDropDown className={style().icon()} />
      </div>
    );
  },
);

Select.displayName = 'Select';

import { field } from '@atomic/obj.form/field.component.styled';
import { tv } from 'tailwind-variants';

const { border, content } = field();

export const style = tv({
  slots: {
    wrapper: 'relative',
    field: [border(), content(), 'cursor-pointer pr-[42px]'],
    icon: 'pointer-events-none absolute top-1/2 right-xs -translate-y-1/2 text-neutral [&>svg]:h-lg [&>svg]:w-lg',
  },
  variants: {
    invalid: {
      true: {
        field: [content({ invalid: true }), border({ invalid: true })],
      },
    },
  },
});

import { H3, InputLabel } from '@atomic/atm.typography';
import type { Meta, StoryObj } from '@storybook/react';
import { Select } from './select.component';

const meta: Meta<typeof Select> = {
  title: 'Atomic/Atoms/Select',
};

export default meta;

type Story = StoryObj<typeof Select>;

export const Default: Story = {
  args: {
    options: [
      { value: 'easy', label: 'Fácil' },
      { value: 'normal', label: 'Normal' },
      { value: 'high', label: 'Difícil' },
    ],
    defaultValue: 'normal',
  },
  render: args => (
    <div>
      <H3>Select</H3>
      <InputLabel htmlFor="select-story">Dificuldade</InputLabel>
      <Select id="select-story" {...args} />
    </div>
  ),
};

