      .insert(questTable)
      .values({ ...input, id, createdAt })
      .returning();

    return toQuestData(quest!);
  },

  async findOneById(id: string): Promise<QuestData | null> {
    const quest = await dbClient.query.questTable.findFirst({ where: { id, deletedAt: { isNull: true } } });
